 * created owner scores at most 5 points (tenure being the only route to 6), a new
 * owner never exceeds level 3.
 */
@Transient
public int getMembershipLevel() {
    int points = getMembershipPoints();
    if (points <= 1) {
        return 1;
    }
    if (points <= 3) {
        return 2;
    }
    if (points <= 5) {
        return 3;
    }
    return 4;
}

